    /// <param name="msghash32">the 32-byte message hash being signed. seckey:    pointer to a 32-byte secret key. noncefp:   pointer to a nonce generation function. If NULL, secp256k1_nonce_function_default is used. ndata:     pointer to arbitrary data used by the nonce generation function (can be NULL for secp256k1_nonce_function_default).</param>
    /// <param name="seckey">pointer to a 32-byte secret key.</param>
